        state: [E(.forensic, 3, "Lab Report", "40 tablets containing fentanyl, 4.1 grams in all."),
                E(.physical, 2, "Cash and Second Phone", "$1,300 in twenties folded in a rubber band, and a prepaid phone with dozens of texts asking for \"blues.\"", .search)],
        defense: [E(.document, 1, "Car Registration", "The car is registered to {DL}'s cousin.")],
        witnessRole: "Narcotics detective",
        exam: [.direct("What did the second phone show?", "\"Forty-one texts in two days asking for 'blues,' with prices. Some answered with a location.\""),
               .direct("Why does the amount matter?", "\"Forty pills packaged together, with cash in small bills and a phone used for orders, is a sale amount, not personal use.\""),
               .cross("The car belongs to {DL}'s cousin.", "\"It does. {DL} was the only one in it.\""),
